-- Show summary
SELECT stream, class, semester, COUNT(*) as count
FROM students
WHERE roll_no NOT LIKE '25MCA%'
GROUP BY stream, class, semester
ORDER BY stream, semester, class;

SELECT 'Total New Students Added:' as message, COUNT(*) as count
FROM students
WHERE roll_no NOT LIKE '25MCA%';
